function injectBoard() {
  if (!document.getElementById('tablon-board-css')) {
    const s = document.createElement('style');
    s.id = 'tablon-board-css';
    s.textContent = BOARD_CSS;
    document.head.appendChild(s);
  }
  const root = document.getElementById('board-root');
  if (!root) throw new Error('falta el tablón');
  if (!root.dataset.ready) {
    root.innerHTML = BOARD_HTML;
    root.dataset.ready = '1';
  }
  root.hidden = false;
  const sh = root.querySelector('#shell');
  if (sh) sh.hidden = false;
  if (!boardLogicReady) {
    initBoardLogic();
    boardLogicReady = true;
  }
}


function flashValidateEgg() {
  if (!window.tablonAdult) return;
  let el = document.getElementById('validate-egg');
  if (!el) {
    el = document.createElement('div');
    el.id = 'validate-egg';
    el.setAttribute('aria-hidden', 'true');
    el.textContent = '🙊';
    el.style.cssText = 'position:fixed;left:50%;top:42%;transform:translate(-50%,-50%);font-size:2.6rem;z-index:80;pointer-events:none;line-height:1';
    document.body.appendChild(el);
  }
  el.hidden = false;
  if (el._hide) clearTimeout(el._hide);
  el._hide = setTimeout(function () { el.hidden = true; }, 1000);
}
window.tablonFlashValidateEgg = flashValidateEgg;

