function startDataListeners(user, setStatus) {
  const firestore = window.tablonFirebase.api;
  const firestoreDb = window.tablonFirebase.firestore;
  const state = window.tablonState;
  const render = () => window.tablonRender?.();
  if (listenersUser === user.uid) return;
  unsubscribe.forEach(fn => fn());
  unsubscribe = [];
  listenersUser = user.uid;
  const listen = (name, ref, apply) => unsubscribe.push(firestore.onSnapshot(ref, snap => { apply(snap); render(); }, error => { console.error(`[tablon:${name}]`, error); setStatus('Acceso · no se pueden leer ' + name); }));
  const childScope = firestore.query(firestore.collection(firestoreDb, 'tasks'), firestore.where('assignee', 'in', ['Nacho', 'Luz', 'shared']));
  listen('balances', firestore.query(firestore.collection(firestoreDb, 'balances'), firestore.where(firestore.documentId(), 'in', ['Nacho', 'Luz'])), snap => { for (const doc of snap.docs) if (state.children[doc.id]) state.children[doc.id].points = Number(doc.data().points || 0); });
  listen('tasks', childScope, snap => {
    state.tasks = snap.docs.map(doc => {
      const d = doc.data();
      return { id: doc.id, ...d, title: d.title || d.name, icon: d.icon || '✅', child: d.child || d.assignee, scope: d.scope || (d.assignee === 'shared' ? 'shared' : 'individual'), frequency: d.frequency || ((d.cadence || 'Diaria') === 'Semanal' ? 'weekly' : 'daily'), days: d.days, cadence: d.cadence || ({ daily: 'Diaria', weekly: 'Semanal' }[d.frequency] || 'Diaria'), points: Number(d.points || 0), catalogStatus: d.status === 'archived' ? 'archived' : 'active', instanceStatus: null, status: d.status === 'archived' ? 'archived' : 'open' };
    }).filter(t => t.catalogStatus !== 'archived');
    const ids = state.tasks.map(t => t.id);
    if (ids.length) {
      const instanceQuery = firestore.query(firestore.collection(firestoreDb, 'taskInstances'), firestore.where('taskId', 'in', ids.slice(0, 30)));
      const applyTaskInstances = snap => {
        if (!snap) return;
        lastInstanceSnap = snap;
        const viewDate = window.tablonAdult && typeof window.tablonBoardDate === 'function' ? window.tablonBoardDate() : new Date();
        (window.tablonApplyInstanceSnapshot)(state.tasks, snap.docs, viewDate);
        render();
      };
      window.tablonApplyInstances = () => applyTaskInstances(lastInstanceSnap);
      listen('taskInstances', instanceQuery, snap => applyTaskInstances(snap));
    }
  });
  listen('rewards', firestore.collection(firestoreDb, 'rewards'), snap => {
    state.rewards = snap.docs.map(doc => {
      const d = doc.data();
      return { id: doc.id, ...d, status: d.status === 'active' ? 'available' : (d.status || 'available'), title: d.title || d.name, icon: d.icon || '🎁', child: d.child || d.assignee, cost: Number(d.cost ?? d.points ?? 0), repeatable: Boolean(d.repeatable) };
    }).filter(r => r.status !== 'archived');
  });
  listen('redemptions', firestore.query(firestore.collection(firestoreDb, 'redemptions'), firestore.where('childId', 'in', ['Nacho', 'Luz'])), snap => {
    for (const doc of snap.docs) {
      const d = doc.data(), r = state.rewards.find(x => x.id === d.rewardId);
      if (r) {
        r.status = d.status === 'validated' ? (r.repeatable ? 'available' : 'spent') : d.status;
        r.redemptionId = doc.id;
        r.requestedAt = d.createdAt?.toDate?.()?.toLocaleString('es-ES', { timeZone: 'Europe/Madrid', hourCycle: 'h23' }) || r.requestedAt;
      }
    }
  });
  if (window.tablonAdult) listen('history', firestore.collection(firestoreDb, 'history'), snap => {
    state.history = snap.docs.map(doc => ({ id: doc.id, ...doc.data() }));
  });
}

function stopDataListeners() {
  unsubscribe.forEach(fn => fn());
  unsubscribe = [];
  listenersUser = null;
  lastInstanceSnap = null;
  if (window.tablonState) {
    window.tablonState.tasks = [];
    window.tablonState.rewards = [];
    window.tablonState.history = [];
    window.tablonState.children.Nacho.points = 0;
    window.tablonState.children.Luz.points = 0;
    window.tablonRender?.();
  }
}

const houseName = () => ['Garc', 'ía ', 'Oliv', 'as'].join('');

export async function mount({ user, claims, setStatus }) {
  const firebase = window.tablonFirebase;
  const firestoreApi = firebase.api;
  const firestoreDb = firebase.firestore;
  const isChild = claims.childRole === 'supervised';
  if (!isChild) {
    await firestoreApi.getDoc(firestoreApi.doc(firestoreDb, 'balances', 'Nacho'));
  }
  injectBoard();
  window.tablonAdult = !isChild;
  window.tablonChild = isChild;
  if (isChild && typeof window.tablonSetBoardDay === 'function') window.tablonSetBoardDay('today');
  const n = 'Tablón Familiar ' + houseName();
  document.title = n;
  const h = document.querySelector('.top h1');
  if (h) h.textContent = n;
  startDataListeners(user, setStatus);
  window.tablonRender?.();
}

export function unmount() {
  stopDataListeners();
  window.tablonAdult = false;
  window.tablonChild = false;
  if (typeof window.tablonSetBoardDay === 'function') window.tablonSetBoardDay('today');
  const root = document.getElementById('board-root');
  if (root) {
    const sh = root.querySelector('#shell');
    if (sh) sh.hidden = true;
    root.hidden = true;
  }
  document.title = 'Tablón';
  const h = document.querySelector('.top h1');
  if (h) h.textContent = 'Tablón';
}
